using System.Diagnostics.CodeAnalysis;

public sealed record Job(string Id, int Priority);

public interface IPriorityJobQueue
{
    void Enqueue(Job job);
    bool TryDequeue([MaybeNullWhen(false)] out Job job);
}

public sealed class PriorityJobQueue : IPriorityJobQueue
{
    private readonly object _sync = new();
    private readonly PriorityQueue<Job, (int Priority, long Seq)> _queue = new();
    private long _sequence;

    public void Enqueue(Job job)
    {
        lock (_sync)
        {
            _queue.Enqueue(job, (-job.Priority, _sequence++));
        }
    }

    public bool TryDequeue([MaybeNullWhen(false)] out Job job)
    {
        lock (_sync)
        {
            return _queue.TryDequeue(out job, out _);
        }
    }
}
